            Node("leaf_has_adjacent_failure", "leaf has adjacent failure", "Exact declaration: theorem leaf_has_adjacent_failure {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (hminimal : Minimal adjacency selection) (leaf support : Vertex) (hleaf : selection leaf) (hhigh : High adjacency selection support) (hsupport : adjacency leaf support) (hunique : ∀ neighbor, selection neighbor → adjacency leaf neighbor → neighbor = support) : ∃ outside, Failure adjacency selection leaf outside ∧ adjacency outside leaf.", DescribeRole.Theorem),
            Node("leaf_failure_other_neighbor_is_isolated", "leaf failure other neighbor is isolated", "Exact declaration: theorem leaf_failure_other_neighbor_is_isolated {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (leaf support outside other : Vertex) (hhigh : High adjacency selection support) (hunique : ∀ neighbor, selection neighbor → adjacency leaf neighbor → neighbor = support) (hfailure : Failure adjacency selection leaf outside) (hother : selection other) (hdifferent : other ≠ leaf) (hedge : adjacency outside other) : ∀ endpoint, selection endpoint → ¬ adjacency other endpoint.", DescribeRole.Theorem),
            Node("high_adjacent_failure_other_neighbor_is_isolated", "high adjacent failure other neighbor is isolated", "Exact declaration: theorem high_adjacent_failure_other_neighbor_is_isolated {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (htrianglefree : ∀ outside first second, adjacency outside first → adjacency outside second → adjacency first second → False) (deleted outside other : Vertex) (hfailure : Failure adjacency selection deleted outside) (hdeletededge : adjacency outside deleted) (hotheredge : adjacency outside other) (hother : selection other) (hdifferent : other ≠ deleted) : ∀ endpoint, selection endpoint → ¬ adjacency other endpoint.", DescribeRole.Theorem),
            Node("shared_leaf_high_witness_has_good_support_owner", "shared leaf high witness has good support owner", "Exact declaration: theorem shared_leaf_high_witness_has_good_support_owner {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (htrianglefree : ∀ outside first second, adjacency outside first → adjacency outside second → adjacency first second → False) (leaf support deleted outside : Vertex) (hleaf : selection leaf) (hsupport : selection support) (hleafedge : adjacency leaf support) (houtsideedge : adjacency outside leaf) (hunique : ∀ neighbor, selection neighbor → adjacency leaf neighbor → neighbor = support) (hhigh : High adjacency selection deleted) (hfailure : Failure adjacency selection deleted outside) : deleted = support ∧ ¬ adjacency outside deleted.", DescribeRole.Theorem)), []));
